registry = {}
all_modes = ["none", "normal", "multiway", "newnode", "multiway_newnode", "conv_multiway_newnode", "conv_normal", "gist"]

def implements(names, modes):
    def _wrapper(C):
        for m in modes:
            assert m in all_modes
            if m not in registry:
                registry[m] = {}
            for n in names:
                if n not in registry[m]:
                    registry[m][n] = []
                registry[m][n].append(C)
        C.names = names
        return C
    return _wrapper


def list_ops(mode, name):
    return registry[mode][name]

